import process from 'node:process';
import * as p from '@clack/prompts';
import { coerceVersion } from '@sveltejs/sv-utils';
import communityAddons from '../../community-addons.json' with { type: 'json' };
import pkg from '../../package.json' with { type: 'json' };
import type { AddonInput } from './config.ts';

/** Generated by `scripts/update-community-addons.js`. `downloads` is weekly. */
export type CommunityAddon = { name: string; description: string; sv: string; downloads: number };

const compact = new Intl.NumberFormat('en', { notation: 'compact' });

// same rule as `verifyPackage`, so a listed add-on installs without a compatibility warning
export function compatibleCommunityAddons(
	list: CommunityAddon[] = communityAddons,
	svVersion: string = pkg.version
): CommunityAddon[] {
	const major = coerceVersion(svVersion).major;
	return list.filter((addon) => {
		const addonMajor = coerceVersion(addon.sv).major;
		return addonMajor !== undefined && addonMajor === major;
	});
}

export async function promptCommunityAddons(list: CommunityAddon[]): Promise<AddonInput[]> {
	const selected = await p.autocompleteMultiselect({
		message: 'Which community add-ons would you like to add?',
		options: list.map(({ name, description, downloads }) => ({
			value: name,
			label: name,
			hint: `${description} · ${compact.format(downloads)}/wk`
		})),
		required: false
	});
	if (p.isCancel(selected)) {
		p.cancel('Operation cancelled.');
		process.exit(1);
	}
	return selected.map((specifier) => ({ specifier, options: [] }));
}
